css:
:root {
  --bg-base: #0a0a0a;
  --bg-surface: #111111;
  --bg-card: #1f1f1f;
  --border: #2a2a2a;
  --text: #fafafa;
  --text-muted: #a1a1aa;
  --accent: #0ea5e9;
  --success: #22c55e;
  --danger: #ef4444;
  --warning: #f59e0b;

  /* Uma cor por fonte de receita — a mesma em pílula, gráfico e avatar. */
  --src-empresa: #0ea5e9;
  --src-impressionart: #8b5cf6;
  --src-moto: #f59e0b;
  --src-mos: #22c55e;

  --fonte: 'Manrope', sans-serif;
  --fonte-titulo: 'Sora', sans-serif;
  --fonte-mono: 'JetBrains Mono', monospace;
}

body { background: var(--bg-base); color: var(--text); font-family: var(--fonte); }

/* Número em tabela, card ou badge nunca "dança" ao atualizar. */
.bs-num { font-variant-numeric: tabular-nums; }

.bs-metas { width: min(520px, 100%); display: flex; flex-direction: column; gap: 12px; }

.bs-meta { padding: 16px; border: 1px solid var(--border); border-radius: 12px; background: var(--bg-surface); }

.bs-meta-topo { display: flex; align-items: center; justify-content: space-between; gap: 8px; margin-bottom: 12px; }
.bs-meta-titulo { font-family: var(--fonte-titulo); font-size: 15px; font-weight: 600; color: var(--text); }
.bs-meta-titulo span { font-family: var(--fonte); font-size: 11px; font-weight: 400; color: var(--text-muted); }
.bs-meta-link { font-size: 12px; font-weight: 600; color: var(--accent); text-decoration: none; }
.bs-meta-link:hover { text-decoration: underline; }

.bs-meta-linha { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; margin-bottom: 8px; }
.bs-meta-valor {
  min-width: 0;
  font-family: var(--fonte-titulo); font-size: 19px; font-weight: 600;
  letter-spacing: -0.02em; color: var(--text);
}
.bs-meta-valor span { font-family: var(--fonte); font-size: 12px; font-weight: 500; color: var(--text-muted); }
.bs-meta-pct { flex-shrink: 0; font-size: 13px; font-weight: 600; color: var(--accent); }
/* O valor cresce a partir de 768px: no celular, 22px com o "de R$ ..." ao
   lado estoura a linha antes de o truncamento ajudar. */
@media (min-width: 768px) {
  .bs-meta-valor { font-size: 22px; }
  .bs-meta-valor span { font-size: 13px; }
}

.bs-barra { height: 8px; overflow: hidden; border-radius: 999px; background: var(--bg-card); }
.bs-barra-fill {
  height: 100%; border-radius: 999px; background: var(--accent);
  transition: width 0.3s ease;
}

/* Bateu a meta: percentual e barra viram verde juntos. A largura satura em
   100% — barra estourando o trilho não informa nada, o número já diz 118%. */
.bs-meta-ok { color: var(--success); }
.bs-meta-ok-bg { background: var(--success); }
